#include <algorithm>
#include <deque>
#include <fstream>
#include <limits>
#include <vector>
int main() {
    std::ifstream in("cbarn.in");
    std::ofstream out("cbarn.out");
    int n;
    in >> n;
    std::vector<int> count(n);
    for (int& c : count) in >> c;
    long long best = std::numeric_limits<long long>::max();
    for (int start = 0; start < n; ++start) {
        std::deque<int> waiting;
        long long energy = 0;
        bool valid = true;
        for (int offset = 0; offset < n; ++offset) {
            for (int j = 0; j < count[(start + offset) % n]; ++j) waiting.push_back(offset);
            if (waiting.empty()) { valid = false; break; }
            long long distance = offset - waiting.front();
            waiting.pop_front();
            energy += distance * distance;
        }
        if (valid) best = std::min(best, energy);
    }
    out << best << '\n';
}
