#include <algorithm>
#include <fstream>
#include <utility>
#include <vector>
int main() {
    std::ifstream in("balancing.in");
    std::ofstream out("balancing.out");
    int n;
    in >> n;
    std::vector<std::pair<int, int>> cows(n);
    std::vector<int> horizontal{0};
    for (auto& cow : cows) {
        in >> cow.first >> cow.second;
        horizontal.push_back(cow.second + 1);
    }
    std::sort(cows.begin(), cows.end());
    std::sort(horizontal.begin(), horizontal.end());
    horizontal.erase(std::unique(horizontal.begin(), horizontal.end()), horizontal.end());
    int answer = n;
    for (int b : horizontal) {
        int leftLow = 0, leftHigh = 0, rightLow = 0, rightHigh = 0;
        for (const auto& cow : cows) {
            if (cow.second < b) ++rightLow;
            else ++rightHigh;
        }
        answer = std::min(answer, std::max(rightLow, rightHigh));
        for (int i = 0; i < n;) {
            int j = i;
            while (j < n && cows[j].first == cows[i].first) {
                if (cows[j].second < b) { ++leftLow; --rightLow; }
                else { ++leftHigh; --rightHigh; }
                ++j;
            }
            answer = std::min(answer, std::max({leftLow, leftHigh, rightLow, rightHigh}));
            i = j;
        }
    }
    out << answer << '\n';
}
