#include <algorithm>
#include <cstdlib>
#include <fstream>
#include <queue>
#include <vector>
int main() {
    std::ifstream in("pails.in");
    std::ofstream out("pails.out");
    int x, y, k, target;
    in >> x >> y >> k >> target;
    int width = y + 1;
    std::vector<int> distance((x + 1) * width, -1);
    std::queue<int> q;
    distance[0] = 0;
    q.push(0);
    int answer = target;
    auto add = [&](int a, int b, int d) {
        int state = a * width + b;
        if (distance[state] == -1) { distance[state] = d; q.push(state); }
    };
    while (!q.empty()) {
        int state = q.front();
        q.pop();
        int a = state / width, b = state % width;
        answer = std::min(answer, std::abs(target - a - b));
        if (distance[state] == k) continue;
        int next = distance[state] + 1;
        add(x, b, next);
        add(a, y, next);
        add(0, b, next);
        add(a, 0, next);
        int toY = std::min(a, y - b), toX = std::min(b, x - a);
        add(a - toY, b + toY, next);
        add(a + toX, b - toX, next);
    }
    out << answer << '\n';
}
